changeSet.sql:
IF OBJECT_ID(N'RedGateSchema.GetRecentAudits','P') IS NOT NULL
  DROP PROCEDURE RedGateSchema.GetRecentAudits;

EXEC(N'
  CREATE PROCEDURE RedGateSchema.GetRecentAudits
      @Days INT = 30,
      @MinCustomerID INT = NULL,
      @Source NVARCHAR(50) = NULL
  AS
  BEGIN
      SET NOCOUNT ON;

      SELECT TOP (50)
          a.AuditID,
          a.CustomerID,
          a.Source,
          a.CreatedAt
      FROM RedGateSchema.FeedbackAudit a
      WHERE a.CreatedAt > DATEADD(day, -@Days, SYSUTCDATETIME())
        AND (@MinCustomerID IS NULL OR a.CustomerID >= @MinCustomerID)
        AND (@Source IS NULL OR a.Source = @Source)
      ORDER BY a.CreatedAt DESC;
  END
');

IF OBJECT_ID(N'RedGateSchema.CountRecentAudits','FN') IS NOT NULL
  DROP FUNCTION RedGateSchema.CountRecentAudits;

EXEC(N'
  CREATE FUNCTION RedGateSchema.CountRecentAudits
  (
    @Days INT,
    @Source NVARCHAR(50) = NULL
  )
  RETURNS INT
  AS
  BEGIN
    RETURN (
      SELECT COUNT(*) 
      FROM RedGateSchema.FeedbackAudit a
      WHERE a.CreatedAt > DATEADD(day, -@Days, SYSUTCDATETIME())
        AND (@Source IS NULL OR a.Source = @Source)
    );
  END
');
